// One-time data migration: reads every row out of the app's SQLite
// database and emits a plain .sql file of INSERT statements that loads
// the same data into the Postgres schema in migration/postgres-schema.sql.
//
// Deliberately generates a .sql file rather than connecting to Postgres
// directly from this script -- this sandbox has no npm registry access
// (confirmed in an earlier session), so there's no `pg` driver available
// here to open a live connection. Piping the generated file through
// `psql` sidesteps that entirely: psql is a plain SQL client, not an
// npm package, and is already installed. This also means the exact same
// generated file can be run against Nina's real Supabase database later
// via psql from her own machine, with no code changes.
//
// Usage:
//   node migration/sqlite-to-postgres.js <path-to-roster.db> <output.sql>
//
// IMPORTANT: run this against a roster.db that has already been through
// one normal app startup (`node server.js`, or just `require('./lib/db').getDb()`)
// so every self-healing migration/table has already been created --
// otherwise newer tables (billing_group, payment_receipt) or columns
// won't exist yet to read from. See the migration README for the full
// checklist.

const { DatabaseSync } = require('node:sqlite');
const fs = require('node:fs');
const path = require('node:path');

const [, , dbPathArg, outPathArg] = process.argv;
if (!dbPathArg || !outPathArg) {
  console.error('Usage: node sqlite-to-postgres.js <path-to-roster.db> <output.sql>');
  process.exit(1);
}
const dbPath = path.resolve(dbPathArg);
const outPath = path.resolve(outPathArg);

const db = new DatabaseSync(dbPath);

// Order matters: children after parents, so foreign keys never point at a
// row that doesn't exist yet. Matches the dependency order in
// postgres-schema.sql.
const TABLES = [
  'teacher',
  'curriculum_level',
  'student',
  'billing_group',
  'subject_enrollment',
  'schedule_slot',
  'attendance',
  'monthly_progress',
  'app_state',
  'ashr_award',
  'payment_record',
  'payment_receipt',
];

// student.billing_group_id references billing_group, but billing_group
// doesn't reference student -- so student rows can load before
// billing_group rows only if billing_group_id is deferred. Simpler: load
// billing_group before student, and since billing_group has no FK back to
// student, that's safe. (Already reflected in TABLES above.)

function sqlLiteral(value) {
  if (value === null || value === undefined) return 'NULL';
  if (typeof value === 'number') {
    if (Number.isInteger(value)) return String(value);
    return String(value);
  }
  if (typeof value === 'bigint') return value.toString();
  // Everything else (including SQLite's TEXT/BLOB-as-string) becomes a
  // single-quoted Postgres string literal, with embedded quotes doubled
  // and backslashes left alone (standard_conforming_strings is on by
  // default in Postgres, so backslashes are literal, not escapes).
  const s = String(value).replace(/'/g, "''");
  return `'${s}'`;
}

function tableExists(name) {
  const row = db.prepare(
    `SELECT 1 FROM sqlite_master WHERE type='table' AND name = ?`
  ).get(name);
  return !!row;
}

const lines = [];
lines.push('-- Generated by migration/sqlite-to-postgres.js -- do not hand-edit.');
lines.push('-- Run with: psql "<connection-string>" -f ' + path.basename(outPath));
lines.push('BEGIN;');
lines.push('SET session_replication_role = replica;'); // skip FK checks during bulk load, restored after

let totalRows = 0;
const rowCounts = {};

for (const table of TABLES) {
  if (!tableExists(table)) {
    lines.push(`-- table "${table}" not present in source database, skipped`);
    rowCounts[table] = 0;
    continue;
  }
  const cols = db.prepare(`PRAGMA table_info(${table})`).all().map((c) => c.name);
  const rows = db.prepare(`SELECT * FROM ${table}`).all();
  rowCounts[table] = rows.length;
  totalRows += rows.length;
  if (!rows.length) continue;

  lines.push(`-- ${table}: ${rows.length} row(s)`);
  const colList = cols.map((c) => `"${c}"`).join(', ');
  for (const row of rows) {
    const vals = cols.map((c) => sqlLiteral(row[c])).join(', ');
    lines.push(`INSERT INTO ${table} (${colList}) VALUES (${vals});`);
  }
}

// Reset every SERIAL sequence to MAX(id)+1 so the next app-generated
// INSERT (no explicit id) doesn't collide with an id we just loaded
// explicitly above.
lines.push('-- Reset auto-increment sequences past the highest migrated id');
for (const table of TABLES) {
  if (!rowCounts[table]) continue;
  const cols = db.prepare(`PRAGMA table_info(${table})`).all().map((c) => c.name);
  if (!cols.includes('id')) continue; // app_state uses a text key, not id
  lines.push(
    `SELECT setval(pg_get_serial_sequence('${table}', 'id'), COALESCE((SELECT MAX(id) FROM ${table}), 1), true);`
  );
}

lines.push('SET session_replication_role = DEFAULT;');
lines.push('COMMIT;');

fs.writeFileSync(outPath, lines.join('\n') + '\n', 'utf8');

console.log('Row counts by table:');
for (const table of TABLES) {
  console.log(`  ${table.padEnd(20)} ${rowCounts[table]}`);
}
console.log(`Total rows: ${totalRows}`);
console.log(`Wrote ${outPath}`);
